let heartbeatInterval: NodeJS.Timeout | null = null;
let inactivityTimeout: NodeJS.Timeout | null = null;
let broadcast: BroadcastChannel | null = null;
let lastPayload: Record<string, any> = {};

const TAB_ID = Math.random().toString(36).substring(2, 15);

const CHANNEL_NAME = 'chatbot_heartbeat_channel';
const ACTIVE_TAB_KEY = 'chatbot_active_tab';

const DEBUG = false;
const log = (...args: any[]) => {
  if (DEBUG) {
    console.log(`[Tab ${TAB_ID.substring(0, 4)}]`, ...args);
  }
};


export const startHeartbeat = (payload: Record<string, any>) => {
  const HEARTBEAT_INTERVAL = payload?.heartbeatInterval * 1000;
  lastPayload = payload; 

  log('Checking if this tab should start heartbeat');

  
  if (document.visibilityState !== 'visible') {
    log('Tab is not visible, entering listen-only mode');
    listenForActiveTabChanges();
    return;
  }

  
  const activeTab = localStorage.getItem(ACTIVE_TAB_KEY);
  if (activeTab) {
    try {
      const { tabId, timestamp } = JSON.parse(activeTab);
      const now = Date.now();
      
      // If another tab is already active and recently updated (last 5 seconds)
      if (tabId !== TAB_ID && now - timestamp < 5000) {
        log('Another tab is already active:', tabId);
        listenForActiveTabChanges();
        return;
      }
    } catch (e) {
      log('Error parsing active tab info');
    }
  }

  // This tab becomes the active tab
  becomeActiveTab();

  // Start heartbeat in this tab
  stopHeartbeat(); // in case it was running
  sendHeartbeat({ ...payload, status: 'active' });

  heartbeatInterval = setInterval(() => {
    // Only send heartbeat if still the active tab
    if (isActiveTab()) {
      sendHeartbeat({ ...payload, status: 'active' });
    } else {
      log('No longer the active tab, stopping heartbeat');
      stopHeartbeat();
    }
  }, HEARTBEAT_INTERVAL);

  resetInactivityTimer(payload);
  log('Successfully started heartbeat');
};


function becomeActiveTab() {
  log('Becoming the active tab');
  localStorage.setItem(ACTIVE_TAB_KEY, JSON.stringify({ 
    tabId: TAB_ID,
    timestamp: Date.now()
  }));
  
  // Announce to other tabs
  broadcastActiveTab();
  
 
  if (!heartbeatInterval) {
    setInterval(() => {
      // Only update if we're still visible
      if (document.visibilityState === 'visible') {
        localStorage.setItem(ACTIVE_TAB_KEY, JSON.stringify({ 
          tabId: TAB_ID,
          timestamp: Date.now()
        }));
      }
    }, 2000);
  }
}


function broadcastActiveTab() {
  if (!broadcast) {
    broadcast = new BroadcastChannel(CHANNEL_NAME);
  }
  broadcast.postMessage({ 
    type: 'ACTIVE_TAB_CHANGED',
    tabId: TAB_ID
  });
}


function broadcastInactiveTab() {
  if (!broadcast) {
    broadcast = new BroadcastChannel(CHANNEL_NAME);
  }
  broadcast.postMessage({ 
    type: 'ACTIVE_TAB_RELEASED',
    tabId: TAB_ID
  });
}

/**
 * Checks if this tab is the active tab
 */
function isActiveTab() {
  const activeTab = localStorage.getItem(ACTIVE_TAB_KEY);
  if (!activeTab) return false;
  
  try {
    const { tabId } = JSON.parse(activeTab);
    return tabId === TAB_ID;
  } catch (e) {
    return false;
  }
}

/**
 * Resets the inactivity timer based on user activity
 * @param payload Configuration for the heartbeat
 */
export const resetInactivityTimer = (payload: Record<string, any>) => {
  const INACTIVITY_LIMIT = payload?.inactivityLimit * 1000;

  if (inactivityTimeout) clearTimeout(inactivityTimeout);

  inactivityTimeout = setTimeout(() => {
    log('Inactivity timeout reached');
    sendHeartbeat({ ...payload, status: 'inactive' });
    stopHeartbeat();

    // Release active tab status
    releaseActiveTab();
  }, INACTIVITY_LIMIT);
};

/**
 * Stops all heartbeat-related processes
 */
export const stopHeartbeat = () => {
  if (heartbeatInterval) {
    clearInterval(heartbeatInterval);
    heartbeatInterval = null;
  }

  if (inactivityTimeout) {
    clearTimeout(inactivityTimeout);
    inactivityTimeout = null;
  }
  
  log('Heartbeat stopped');
};

/**
 * Releases the active tab status
 */
function releaseActiveTab() {
  log('Releasing active tab status');
  const activeTab = localStorage.getItem(ACTIVE_TAB_KEY);
  
  if (activeTab) {
    try {
      const { tabId } = JSON.parse(activeTab);
      // Only remove if this tab owns it
      if (tabId === TAB_ID) {
        localStorage.removeItem(ACTIVE_TAB_KEY);
        broadcastInactiveTab();
      }
    } catch (e) {
      // In case of parsing errors
      localStorage.removeItem(ACTIVE_TAB_KEY);
      broadcastInactiveTab();
    }
  }
}

/**
 * Sends a heartbeat to the server
 * @param body Payload to send with the heartbeat
 */
const sendHeartbeat = async (body: Record<string, any>) => {
  try {
    log('Sending heartbeat:', body.status);
    await fetch('http://localhost:8000/api/v1/heartbeat', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        ...body,
        tabId: TAB_ID,
        isActiveTab: true,
        timestamp: new Date().toISOString(),
      }),
    });
  } catch (error) {
    console.error('Heartbeat failed:', error);
  }
};

/**
 * Listens for active tab changes in other tabs
 */
function listenForActiveTabChanges() {
  if (!broadcast) {
    broadcast = new BroadcastChannel(CHANNEL_NAME);
  }

  broadcast.onmessage = (event: MessageEvent) => {
    const { type, tabId } = event.data;
    
    log('Received message:', type, 'from tab:', tabId);

    if (type === 'ACTIVE_TAB_RELEASED') {
      // Another tab released active status, see if we should take over
      if (document.visibilityState === 'visible') {
        log('Active tab released, attempting to take over');
        // Add a small random delay to prevent race conditions
        setTimeout(() => {
          if (document.visibilityState === 'visible' && lastPayload) {
            startHeartbeat(lastPayload);
          }
        }, Math.random() * 1000);
      }
    } else if (type === 'ACTIVE_TAB_CHANGED') {
      // Another tab became active
      if (tabId !== TAB_ID) {
        log('Another tab became active:', tabId);
        // If we were sending heartbeats, stop
        stopHeartbeat();
      }
    }
  };
}

/**
 * Handles visibility changes for this tab
 */
function handleVisibilityChange() {
  if (document.visibilityState === 'visible') {
    log('Tab became visible');
    
    // If this tab is now visible, check if there's an active tab
    const activeTab = localStorage.getItem(ACTIVE_TAB_KEY);
    
    if (!activeTab) {
      log('No active tab found, becoming active');
      // No active tab, take over
      if (lastPayload && Object.keys(lastPayload).length > 0) {
        startHeartbeat(lastPayload);
      }
    } else {
      try {
        const { tabId, timestamp } = JSON.parse(activeTab);
        const now = Date.now();
        
        // If the active tab hasn't updated in 5 seconds, take over
        if (now - timestamp > 5000) {
          log('Active tab appears stale, taking over');
          if (lastPayload && Object.keys(lastPayload).length > 0) {
            startHeartbeat(lastPayload);
          }
        }
      } catch (e) {
        // Error parsing active tab, take over
        if (lastPayload && Object.keys(lastPayload).length > 0) {
          startHeartbeat(lastPayload);
        }
      }
    }
  } else {
    log('Tab became hidden');
    
    // If this tab is now hidden and is the active tab, release that status
    if (isActiveTab()) {
      log('Active tab became hidden, releasing status');
      releaseActiveTab();
      stopHeartbeat();
    }
  }
}

/**
 * Initializes the heartbeat control system
 * @param payload Configuration for the heartbeat
 */
export const initHeartbeatControl = (payload: Record<string, any>) => {
  lastPayload = payload;
  
  log('Initializing heartbeat control with tab ID:', TAB_ID);
  
  // Clean up any existing listeners
  if (broadcast) {
    broadcast.close();
    broadcast = null;
  }
  
  // Set up visibility change listener
  document.removeEventListener('visibilitychange', handleVisibilityChange);
  document.addEventListener('visibilitychange', handleVisibilityChange);
  
  // Check for localStorage events in case another tab changes the active tab directly
  window.addEventListener('storage', (event) => {
    if (event.key === ACTIVE_TAB_KEY) {
      if (event.newValue === null) {
        log('Active tab status was cleared');
        // Active tab was released
        if (document.visibilityState === 'visible') {
          // Only try to become active if we're visible
          log('Attempting to become active tab');
          setTimeout(() => {
            if (lastPayload && Object.keys(lastPayload).length > 0) {
              startHeartbeat(lastPayload);
            }
          }, Math.random() * 1000); // Small delay to prevent race conditions
        }
      } else {
        try {
          // Update our knowledge of who's the active tab
          const activeTabData = JSON.parse(event.newValue);
          log('Active tab updated via localStorage:', activeTabData.tabId);
          
          // If we thought we were the active tab but someone else took over, stop heartbeat
          if (heartbeatInterval && activeTabData.tabId !== TAB_ID) {
            log('Another tab took over, stopping heartbeat');
            stopHeartbeat();
          }
        } catch (e) {
          // Parsing error, ignore
        }
      }
    }
  });
  
  // Start heartbeat process if this is a visible tab
  startHeartbeat(payload);
  
  // Handle cleanup when page is unloaded
  window.addEventListener('beforeunload', () => {
    log('Tab is being unloaded');
    // If this tab is the active tab, release before unloading
    if (isActiveTab()) {
      releaseActiveTab();
    }
    
    stopHeartbeat();
    if (broadcast) {
      broadcast.close();
    }
  });
  
  // Return the tab ID for reference
  return { tabId: TAB_ID };
};

/**
 * Re-activates the heartbeat after user interaction
 * Use this function to reset the inactivity timer when the user performs actions
 */
export const userActivityDetected = () => {
  // Only reset if this is the active tab
  if (isActiveTab() && lastPayload) {
    resetInactivityTimer(lastPayload);
    
    // If this tab has user activity but isn't visible, it shouldn't be the active tab
    if (document.visibilityState !== 'visible') {
      releaseActiveTab();
    }
  } else if (document.visibilityState === 'visible') {
    // If this tab has activity and is visible, but isn't the active tab,
    // it should become the active tab
    if (lastPayload && Object.keys(lastPayload).length > 0) {
      startHeartbeat(lastPayload);
    }
  }
};